<body class="login-page"><main class="login-shell"><section class="login-art"><div class="dots"></div><div class="login-copy"><div class="text-uppercase small fw-bold"><i class="bi bi-lightning-charge-fill me-2"></i>Puihaha Electric</div><h1>Welcome back!</h1><p>You can sign in to access your customer account workspace.</p></div></section><section class="login-form"><h2>Sign In</h2><?php if($message=session()->getFlashdata('error')): ?><div class="alert alert-danger"><?= esc($message) ?></div><?php endif; ?><?php if($message=session()->getFlashdata('success')): ?><div class="alert alert-success"><?= esc($message) ?></div><?php endif; ?><form action="<?= base_url('login') ?>" method="post"><?= csrf_field() ?><label class="small fw-semibold" for="email">Username or email</label><div class="field"><i class="bi bi-person-fill"></i><input class="form-control" id="email" name="email" type="email" placeholder="Username or email" value="<?= esc(old('email')) ?>" required autofocus></div><label class="small fw-semibold" for="password">Password</label><div class="field"><i class="bi bi-lock-fill"></i><input class="form-control" id="password" name="password" type="password" placeholder="Password" required></div><div class="login-options"><label><input type="checkbox"> Remember me</label><a href="<?= base_url('contact') ?>">Forgot password?</a></div><button class="login-button w-100" type="submit">Sign In</button></form><p class="login-new">New here? <a href="<?= base_url('register') ?>">Create an Account</a></p><a class="back-home" href="<?= base_url() ?>"><i class="bi bi-arrow-left me-1"></i>Back to Home</a></section></main></body></html>
